1	import type { Request } from "express";
2	import { forbidden } from "../errors.js";
3	
4	function isRecord(value: unknown): value is Record<string, unknown> {
5	  return typeof value === "object" && value !== null && !Array.isArray(value);
6	}
7	
8	function hasOwn(value: Record<string, unknown>, key: string) {
9	  return Object.prototype.hasOwnProperty.call(value, key);
10	}
11	
12	function prefixPath(prefix: string, key: string) {
13	  return prefix.length > 0 ? `${prefix}.${key}` : key;
14	}
15	
16	function collectWorkspaceStrategyCommandPaths(raw: unknown, prefix: string): string[] {
17	  if (!isRecord(raw)) return [];
18	  const paths: string[] = [];
19	  if (hasOwn(raw, "provisionCommand")) {
20	    paths.push(prefixPath(prefix, "provisionCommand"));
21	  }
22	  if (hasOwn(raw, "teardownCommand")) {
23	    paths.push(prefixPath(prefix, "teardownCommand"));
24	  }
25	  return paths;
26	}
27	
28	function collectExecutionWorkspaceConfigCommandPaths(raw: unknown, prefix: string): string[] {
29	  if (!isRecord(raw)) return [];
30	  const paths: string[] = [];
31	  if (hasOwn(raw, "provisionCommand")) {
32	    paths.push(prefixPath(prefix, "provisionCommand"));
33	  }
34	  if (hasOwn(raw, "teardownCommand")) {
35	    paths.push(prefixPath(prefix, "teardownCommand"));
36	  }
37	  if (hasOwn(raw, "cleanupCommand")) {
38	    paths.push(prefixPath(prefix, "cleanupCommand"));
39	  }
40	  return paths;
41	}
