43	export function assertNoAgentHostWorkspaceCommandMutation(req: Request, paths: string[]) {
44	  if (req.actor.type !== "agent" || paths.length === 0) return;
45	  throw forbidden(
46	    `Agent keys cannot modify host-executed workspace commands (${paths.join(", ")}).`,
47	  );
48	}
49	
50	export function collectAgentAdapterWorkspaceCommandPaths(adapterConfig: unknown): string[] {
51	  if (!isRecord(adapterConfig)) return [];
52	  return collectWorkspaceStrategyCommandPaths(
53	    adapterConfig.workspaceStrategy,
54	    "adapterConfig.workspaceStrategy",
55	  );
56	}
57	
58	export function collectProjectExecutionWorkspaceCommandPaths(policy: unknown): string[] {
59	  if (!isRecord(policy)) return [];
60	  return collectWorkspaceStrategyCommandPaths(
61	    policy.workspaceStrategy,
62	    "executionWorkspacePolicy.workspaceStrategy",
63	  );
64	}
65	
66	export function collectProjectWorkspaceCommandPaths(
67	  workspacePatch: unknown,
68	  prefix = "",
69	): string[] {
70	  if (!isRecord(workspacePatch)) return [];
71	  return hasOwn(workspacePatch, "cleanupCommand")
72	    ? [prefixPath(prefix, "cleanupCommand")]
73	    : [];
74	}
75	
76	export function collectIssueWorkspaceCommandPaths(input: {
77	  executionWorkspaceSettings?: unknown;
78	  assigneeAdapterOverrides?: unknown;
79	}): string[] {
80	  const paths: string[] = [];
81	  if (isRecord(input.executionWorkspaceSettings)) {
82	    paths.push(
83	      ...collectWorkspaceStrategyCommandPaths(
84	        input.executionWorkspaceSettings.workspaceStrategy,
85	        "executionWorkspaceSettings.workspaceStrategy",
86	      ),
87	    );
88	  }
89	  if (isRecord(input.assigneeAdapterOverrides)) {
90	    const adapterConfig = input.assigneeAdapterOverrides.adapterConfig;
91	    if (isRecord(adapterConfig)) {
92	      paths.push(
93	        ...collectWorkspaceStrategyCommandPaths(
94	          adapterConfig.workspaceStrategy,
95	          "assigneeAdapterOverrides.adapterConfig.workspaceStrategy",
96	        ),
97	      );
98	    }
99	  }
100	  return paths;
101	}
102	
103	export function collectExecutionWorkspaceCommandPaths(input: {
104	  config?: unknown;
105	  metadata?: unknown;
106	}): string[] {
107	  const paths: string[] = [];
108	  if (input.config !== undefined) {
109	    paths.push(...collectExecutionWorkspaceConfigCommandPaths(input.config, "config"));
110	  }
111	  if (isRecord(input.metadata) && hasOwn(input.metadata, "config")) {
112	    paths.push(...collectExecutionWorkspaceConfigCommandPaths(input.metadata.config, "metadata.config"));
113	  }
114	  return paths;
115	}
